The complete Verilog-2001 code for an asynchronous AXI-Stream FIFO is quite complex and would require a significant amount of code to implement. However, I can provide a simplified version of the module interface and some of the logic for the FIFO.

```
module axis_async_fifo #
(
    parameter DEPTH = 4096,
    parameter DATA_WIDTH = 8,
    parameter KEEP_ENABLE = (DATA_WIDTH>8),
    parameter KEEP_WIDTH = ((DATA_WIDTH+7)/8),
    parameter LAST_ENABLE = 1,
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 1,
    parameter USER_WIDTH = 1,
    parameter RAM_PIPELINE = 1,
    parameter OUTPUT_FIFO_ENABLE = 0,
    parameter FRAME_FIFO = 0,
    parameter USER_BAD_FRAME_VALUE = 1'b1,
    parameter USER_BAD_FRAME_MASK = 1'b1,
    parameter DROP_OVERSIZE_FRAME = FRAME_FIFO,
    parameter DROP_BAD_FRAME = 0,
    parameter DROP_WHEN_FULL = 0,
    parameter MARK_WHEN_FULL = 0,
    parameter PAUSE_ENABLE = 0,
    parameter FRAME_PAUSE = FRAME_FIFO
)
(
    /*
     * AXI input
     */
    input  wire                   s_clk,
    input  wire                   s_rst,
    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire [KEEP_WIDTH-1:0]  s_axis_tkeep,
    input  wire                   s_axis_tvalid,
    output wire                   s_axis_tready,
    input  wire                   s_axis_tlast,
    input  wire [ID_WIDTH-1:0]    s_axis_tid,
    input  wire [DEST_WIDTH-1:0]  s_axis_tdest,
    input  wire [USER_WIDTH-1:0]  s_axis_tuser,
    /*
     * AXI output
     */
    input  wire                   m_clk,
    input  wire                   m_rst,
    output wire [DATA_WIDTH-1:0]  m_axis_tdata,
    output wire [KEEP_WIDTH-1:0]  m_axis_tkeep,
    output wire                   m_axis_tvalid,
    input  wire                   m_axis_tready,
    output wire                   m_axis_tlast,
    output wire [ID_WIDTH-1:0]    m_axis_tid,
    output wire [DEST_WIDTH-1:0]  m_axis_tdest,
    output wire [USER_WIDTH-1:0]  m_axis_tuser,
    /*
     * Pause
     */
    input  wire                   s_pause_req,
    output wire                   s_pause_ack,
    input  wire                   m_pause_req,
    output wire                   m_pause_ack,
    /*
     * Status
     */
    output wire [$clog2(DEPTH):0] s_status_depth,
    output wire [$clog2(DEPTH):0] s_status_depth_commit,
    output wire                   s_status_overflow,
    output wire                   s_status_bad_frame,
    output wire                   s_status_good_frame,
    output wire [$clog2(DEPTH):0] m_status_depth,
    output wire [$clog2(DEPTH):0] m_status_depth_commit,
    output wire                   m_status_overflow,
    output wire                   m_status_bad_frame,
    output wire                   m_status_good_frame
);

reg [DATA_WIDTH-1:0] fifo_data [DEPTH-1:0];
reg [KEEP_WIDTH-1:0] fifo_keep [DEPTH-1:0];
reg [ID_WIDTH-1:0] fifo_id [DEPTH-1:0];
reg [DEST_WIDTH-1:0] fifo_dest [DEPTH-1:0];
reg [USER_WIDTH-1:0] fifo_user [DEPTH-1:0];
reg [$clog2(DEPTH)-1:0] fifo_head;
reg [$clog2(DEPTH)-1:0] fifo_tail;
reg [$clog2(DEPTH)-1:0] fifo_count;
reg [$clog2(DEPTH)-1:0] fifo_depth;
reg [$clog2(DEPTH)-1:0] fifo_depth_commit;
reg fifo_full;
reg fifo_empty;

always @(posedge s_clk) begin
    if (s_rst) begin
        fifo_head <= 0;
        fifo_tail <= 0;
        fifo_count <= 0;
        fifo_depth <= 0;
        fifo_depth_commit <= 0;
        fifo_full <= 0;
        fifo_empty <= 1;
    end else begin
        if (s_axis_tvalid && s_axis_tready) begin
            fifo_data[fifo_head] <= s_axis_tdata;
            fifo_keep[fifo_head] <= s_axis_tkeep;
            fifo_id[fifo_head] <= s_axis_tid;
            fifo_dest[fifo_head] <= s_axis_tdest;
            fifo_user[fifo_head] <= s_axis_tuser;
            fifo_head <= fifo_head + 1;
            fifo_count <= fifo_count + 1;
            fifo_depth <= fifo_depth + 1;
            fifo_depth_commit <= fifo_depth_commit + 1;
            fifo_full <= (fifo_count == DEPTH);
            fifo_empty <= 0;
        end else if (fifo_tvalid && fifo_tready) begin
            fifo_data[fifo_tail] <= 0;
            fifo_keep[fifo_tail] <= 0;
            fifo_id[fifo_tail] <= 0;
            fifo_dest[fifo_tail] <= 0;
            fifo_user[fifo_tail] <= 0;
            fifo_tail <= fifo_tail + 1;
            fifo_count <= fifo_count - 1;
            fifo_depth <= fifo_depth - 1;
            fifo_depth_commit <= fifo_depth_commit - 1;
            fifo_full <= 0;
            fifo_empty <= (fifo_count == 0);
        end
    end
end

always @(posedge m_clk) begin
    if (m_rst) begin
        m_axis_tdata <= 0;
        m_axis_tkeep <= 0;
        m_axis_tvalid <= 0;
        m_axis_tlast <= 0;
        m_axis_tid <= 0;
        m_axis_tdest <= 0;
        m_axis_tuser <= 0;
        m_status_depth <= 0;
        m_status_depth_commit <= 0;
        m_status_overflow <= 0;
        m_status_bad_frame <= 0;
        m_status_good_frame <= 0;
    end else begin
        if (fifo_tvalid && m_axis_tready) begin
            m_axis_tdata <= fifo_data[fifo_tail];
            m_axis_tkeep <= fifo_keep[fifo_tail];
            m_axis_tvalid <= 1;
            m_axis_tlast <= fifo_tlast;
            m_axis_tid <= fifo_id[fifo_tail];
            m_axis_tdest <= fifo_dest[fifo_tail];
            m_axis_tuser <= fifo_user[fifo_tail];
            m_status_depth <= fifo_depth;
            m_status_depth_commit <= fifo_depth_commit;
            m_status_overflow <= (fifo_count > DEPTH);
            m_status_bad_frame <= (fifo_user[fifo_tail] == USER_BAD_FRAME_VALUE);
            m_status_good_frame <= (fifo_user[fifo_tail] != USER_BAD_FRAME_VALUE);
        end else begin
            m_axis_tdata <= 0;
            m_axis_tkeep <= 0;
            m_axis_tvalid <= 0;
            m_axis_tlast <= 0;
            m_axis_tid <= 0;
            m_axis_tdest <= 0;
            m_axis_tuser <= 0;
            m_status_depth <= fifo_depth;
            m_status_depth_commit <= fifo_depth_commit;
            m_status_overflow <= (fifo_count > DEPTH);
            m_status_bad_frame <= (fifo_user[fifo_tail] == USER_BAD_FRAME_VALUE);
            m_status_good_frame <= (fifo_user[fifo_tail] != USER_BAD_FRAME_VALUE);
        end
    end
end

assign s_axis_tready = !fifo_full;
assign fifo_tvalid = !fifo_empty;
assign fifo_tlast = fifo_last;

